#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with godot
# installed with default options (version latest).
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
source "$(dirname "$0")/headless.sh"

# How long the language server may take to accept a connection after the editor starts.
readonly LSP_TIMEOUT=60
readonly HOME_LOCATIONS=(.local/share/godot .config/godot .cache/godot .cache/fontconfig)
readonly GRAPHICAL_LIBRARIES=(libX11.so.6 libwayland-client.so.0 libGL.so.1 libEGL.so.1 libvulkan.so.1 libasound.so.2
  libpulse.so.0)

work="$(mktemp -d)"
trap 'rm -rf "${work}"' EXIT

# Runs a command as root: directly when already root, else through passwordless sudo.
as_root() {
  if [[ "$(id -u)" == 0 ]]; then
    "$@"
  else
    sudo -n "$@"
  fi
}

# Neither the remote user's nor root's home holds HOME_LOCATIONS, which Godot and fontconfig write. Root's home is not
# readable by a non-root remote user.
no_godot_files_in_homes() {
  local home
  local path
  for home in "${HOME}" /root; do
    for path in "${HOME_LOCATIONS[@]}"; do
      if as_root test -e "${home}/${path}"; then
        printf '  found: %s/%s\n' "${home}" "${path}"
        return 1
      fi
    done
  done
}

# Before godot runs at all: its first run writes these locations, so they cannot pass as written by the install.
check "neither the remote user's nor root's home holds any of ${HOME_LOCATIONS[*]}" no_godot_files_in_homes
check "/usr/local/bin holds neither _sc_ nor ._sc_" \
  bash -c '[[ ! -e /usr/local/bin/_sc_ && ! -e /usr/local/bin/._sc_ ]]'
check "no environment variable whose name starts with GODOT is set" bash -c '! compgen -e | grep "^GODOT"'

check "curl is present after the install" command -v curl

# The CA certificate bundle exists and is not empty: Debian's and Ubuntu's ca-certificates generate it at
# /etc/ssl/certs/ca-certificates.crt, Fedora's at /etc/pki/tls/certs/ca-bundle.crt.
ca_bundle_present() {
  local bundle
  for bundle in /etc/ssl/certs/ca-certificates.crt /etc/pki/tls/certs/ca-bundle.crt; do
    if [[ -s "${bundle}" ]]; then
      printf '  found: %s\n' "${bundle}"
      return 0
    fi
  done
  return 1
}
check "the CA certificate bundle is present after the install" ca_bundle_present
check "unzip is present after the install" command -v unzip

# None of GRAPHICAL_LIBRARIES appears in the dynamic linker's cache.
no_graphical_libraries() {
  local cache
  local library
  local status=0
  cache="$(ldconfig -p | awk 'NR > 1 { print $1 }')" || return 1
  for library in "${GRAPHICAL_LIBRARIES[@]}"; do
    if grep -Fqx -- "${library}" <<<"${cache}"; then
      printf '  known to the dynamic linker: %s\n' "${library}"
      status=1
    fi
  done
  return "${status}"
}
check "none of ${GRAPHICAL_LIBRARIES[*]} is known to the dynamic linker" no_graphical_libraries
check "dotnet does not resolve on the remote user's PATH" bash -c '! command -v dotnet'

check "command -v godot resolves, following symbolic links, to /usr/local/bin/godot" godot_resolves_to_usr_local_bin

# `godot --version` exits 0 and prints a version, ".stable.official.", and a hexadecimal commit hash.
godot_reports_official_stable() {
  local output
  output="$(godot --version)" || return 1
  printf "  got '%s'\n" "${output}"
  [[ "${output}" =~ ^[0-9]+(\.[0-9]+)+\.stable\.official\.[0-9a-f]+$ ]]
}
check "godot --version exits 0 and prints a version ending in .stable.official. followed by a commit hash" \
  godot_reports_official_stable

# Computed at run time: the default option installs whatever release the latest-release link names; a release
# published between build and test fails the comparison once.
latest_tag="$(latest_release_tag)"
printf 'the latest-release link names %s\n' "${latest_tag}"
check "godot --version reports the release that the latest-release link points to" \
  godot_reports_version "${latest_tag%-stable}"

project="${work}/project"
make_project "${project}"
check "godot --headless --path <project> --quit on a minimal project exits 0" \
  godot --headless --path "${project}" --quit

# `godot --headless --path $1 --import` exits 0; its combined output goes to ${work}/import.log and is shown when the
# run fails.
imports_project_headless() {
  if ! godot --headless --path "$1" --import </dev/null >"${work}/import.log" 2>&1; then
    tail -n 20 "${work}/import.log"
    return 1
  fi
}
check "godot --headless --path <project> --import on a minimal project exits 0" imports_project_headless "${project}"

# The import's output holds neither line the editor prints when the font configuration library is missing.
no_missing_fontconfig_reported() {
  if grep -i -E 'libfontconfig\.so\.1: cannot open|unable to load fontconfig' "${work}/import.log"; then return 1; fi
}
check "the import's output reports no missing font configuration library" no_missing_fontconfig_reported
check "the project's .godot/ directory exists after the import" test -d "${project}/.godot"

# Starts `godot --headless --editor --path $1 --lsp-port <port>` in the background on a random port that accepted no
# connection before, and succeeds when a TCP connection to 127.0.0.1:<port> succeeds while the editor runs, within
# LSP_TIMEOUT seconds. The editor is then stopped and reaped; its output is shown when the check fails. The port stays
# below 32768, where Linux's default ephemeral range starts: a probe of an unbound port in that range can connect to
# itself and pass.
serves_language_server() {
  local port=$(( 20000 + RANDOM % 12000 ))
  local pid
  local waited=0
  local status=1
  if (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null; then
    printf '  port %s already accepts connections\n' "${port}"
    return 1
  fi
  godot --headless --editor --path "$1" --lsp-port "${port}" </dev/null >"${work}/lsp.log" 2>&1 &
  pid=$!
  while (( waited < LSP_TIMEOUT )) && kill -0 "${pid}" 2>/dev/null; do
    if (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null; then
      status=0
      break
    fi
    sleep 1
    waited=$(( waited + 1 ))
  done
  if (( status == 0 )); then
    printf '  127.0.0.1:%s accepted a connection after about %s s\n' "${port}" "${waited}"
  else
    printf '  127.0.0.1:%s accepted no connection within %s s\n' "${port}" "${waited}"
  fi
  # Stopped with SIGTERM, then SIGKILL after 10 seconds, so a hanging editor cannot hold the test.
  kill "${pid}" 2>/dev/null || true
  for (( waited = 0; waited < 10; waited++ )); do
    if ! kill -0 "${pid}" 2>/dev/null; then break; fi
    sleep 1
  done
  kill -KILL "${pid}" 2>/dev/null || true
  wait "${pid}" || true
  if (( status != 0 )); then tail -n 20 "${work}/lsp.log"; fi
  return "${status}"
}
check "godot --headless --editor --path <project> --lsp-port <port> accepts TCP connections on 127.0.0.1:<port>" \
  serves_language_server "${project}"

# No file under apt's package lists or dnf's cache, whichever of them the image has; parts of both are readable only
# by root.
package_caches_empty() {
  local dir
  local files
  for dir in /var/lib/apt/lists /var/cache/libdnf5; do
    if [[ ! -d "${dir}" ]]; then continue; fi
    files="$(as_root find "${dir}" -type f)" || return 1
    if [[ -n "${files}" ]]; then
      printf '  files remain under %s:\n%s\n' "${dir}" "${files}"
      return 1
    fi
  done
}
check "apt's package lists and dnf's cache hold no file" package_caches_empty
check "no temporary directory, archive, or staged executable of the install remains" no_install_residue

reportResults
